    solution: "programa {\n    funcao inteiro busca_binaria(inteiro vetor[], inteiro tamanho, inteiro valor) {\n        inteiro inicio = 0, fim = tamanho - 1, meio\n        \n        enquanto (inicio <= fim) {\n            meio = (inicio + fim) / 2\n            \n            se (vetor[meio] == valor) {\n                retorne meio\n            } senao se (vetor[meio] < valor) {\n                inicio = meio + 1\n            } senao {\n                fim = meio - 1\n            }\n        }\n        retorne -1 // Não encontrado\n    }\n    \n    funcao inicio() {\n        inteiro numeros[8] = {2, 5, 8, 12, 16, 23, 38, 45}\n        inteiro procurar, resultado\n        \n        escreva(\"Vetor ordenado: \")\n        para (inteiro i = 0; i < 8; i++) {\n            escreva(numeros[i], \" \")\n        }\n        \n        escreva(\"\\n\\nDigite o número a procurar: \")\n        leia(procurar)\n        \n        resultado = busca_binaria(numeros, 8, procurar)\n        \n        se (resultado != -1) {\n            escreva(\"\\n✅ Número \", procurar, \" encontrado na posição \", resultado)\n        } senao {\n            escreva(\"\\n❌ Número \", procurar, \" não encontrado no vetor\")\n        }\n    }\n}",
