    solution: "programa {\n    cadeia nomes[3]\n    inteiro idades[3]\n    real salarios[3]\n    inteiro total_cadastros = 0\n    \n    funcao cadastrar_pessoa() {\n        se (total_cadastros < 3) {\n            escreva(\"\\n=== CADASTRO DE PESSOA ===\\n\")\n            escreva(\"Nome: \")\n            leia(nomes[total_cadastros])\n            escreva(\"Idade: \")\n            leia(idades[total_cadastros])\n            escreva(\"Salário: R$ \")\n            leia(salarios[total_cadastros])\n            \n            total_cadastros++\n            escreva(\"\\n✅ Pessoa cadastrada com sucesso!\")\n        } senao {\n            escreva(\"\\n❌ Limite de cadastros atingido (máximo 3)!\")\n        }\n    }\n    \n    funcao listar_pessoas() {\n        se (total_cadastros == 0) {\n            escreva(\"\\n❌ Nenhuma pessoa cadastrada!\")\n            retorne\n        }\n        \n        escreva(\"\\n=== LISTA DE PESSOAS CADASTRADAS ===\\n\")\n        para (inteiro i = 0; i < total_cadastros; i++) {\n            escreva(\"Pessoa \", i + 1, \":\\n\")\n            escreva(\"  Nome: \", nomes[i], \"\\n\")\n            escreva(\"  Idade: \", idades[i], \" anos\\n\")\n            escreva(\"  Salário: R$ \", salarios[i], \"\\n\\n\")\n        }\n    }\n    \n    funcao buscar_pessoa() {\n        se (total_cadastros == 0) {\n            escreva(\"\\n❌ Nenhuma pessoa cadastrada!\")\n            retorne\n        }\n        \n        cadeia nome_busca\n        logico encontrado = falso\n        \n        escreva(\"\\nDigite o nome a buscar: \")\n        leia(nome_busca)\n        \n        para (inteiro i = 0; i < total_cadastros; i++) {\n            se (nomes[i] == nome_busca) {\n                escreva(\"\\n=== PESSOA ENCONTRADA ===\\n\")\n                escreva(\"Nome: \", nomes[i], \"\\n\")\n                escreva(\"Idade: \", idades[i], \" anos\\n\")\n                escreva(\"Salário: R$ \", salarios[i], \"\\n\")\n                encontrado = verdadeiro\n                pare\n            }\n        }\n        \n        se (nao encontrado) {\n            escreva(\"\\n❌ Pessoa não encontrada!\")\n        }\n    }\n    \n    funcao inicio() {\n        inteiro opcao\n        \n        faca {\n            escreva(\"\\n=== SISTEMA DE CADASTRO ===\\n\")\n            escreva(\"1 - Cadastrar pessoa\\n\")\n            escreva(\"2 - Listar pessoas\\n\")\n            escreva(\"3 - Buscar pessoa\\n\")\n            escreva(\"4 - Estatísticas\\n\")\n            escreva(\"0 - Sair\\n\")\n            escreva(\"\\nEscolha uma opção: \")\n            leia(opcao)\n            \n            escolha (opcao) {\n                caso 1: cadastrar_pessoa() pare\n                caso 2: listar_pessoas() pare\n                caso 3: buscar_pessoa() pare\n                caso 4: \n                    se (total_cadastros > 0) {\n                        real media_idade = 0, media_salario = 0\n                        para (inteiro i = 0; i < total_cadastros; i++) {\n                            media_idade = media_idade + idades[i]\n                            media_salario = media_salario + salarios[i]\n                        }\n                        media_idade = media_idade / total_cadastros\n                        media_salario = media_salario / total_cadastros\n                        \n                        escreva(\"\\n=== ESTATÍSTICAS ===\\n\")\n                        escreva(\"Total de pessoas: \", total_cadastros, \"\\n\")\n                        escreva(\"Média de idade: \", media_idade, \" anos\\n\")\n                        escreva(\"Média salarial: R$ \", media_salario, \"\\n\")\n                    } senao {\n                        escreva(\"\\n❌ Nenhuma pessoa cadastrada!\")\n                    }\n                    pare\n                caso 0: escreva(\"\\n👋 Saindo do sistema...\") pare\n                caso contrario: escreva(\"\\n❌ Opção inválida!\")\n            }\n        } enquanto (opcao != 0)\n    }\n}",
