    solution: "programa {\n    funcao inteiro gerar_numero_aleatorio(inteiro min, inteiro max) {\n        // Simulação de número aleatório (em implementação real usaria função específica)\n        inteiro seed = 17 // Valor fixo para demonstração\n        retorne (seed % (max - min + 1)) + min\n    }\n    \n    funcao inicio() {\n        inteiro numero_secreto, palpite, tentativas = 0, max_tentativas = 7\n        inteiro min_range = 1, max_range = 100\n        logico acertou = falso\n        \n        numero_secreto = gerar_numero_aleatorio(1, 100)\n        \n        escreva(\"=== JOGO DA ADIVINHAÇÃO ===\\n\")\n        escreva(\"Pensei em um número entre 1 e 100!\\n\")\n        escreva(\"Você tem \", max_tentativas, \" tentativas para acertar.\\n\")\n        \n        enquanto (tentativas < max_tentativas e nao acertou) {\n            tentativas++\n            escreva(\"\\nTentativa \", tentativas, \"/\", max_tentativas)\n            escreva(\"\\nRange atual: \", min_range, \" a \", max_range)\n            escreva(\"\\nSeu palpite: \")\n            leia(palpite)\n            \n            se (palpite == numero_secreto) {\n                acertou = verdadeiro\n                escreva(\"\\n🎉 PARABÉNS! Você acertou!\")\n                escreva(\"\\nO número era \", numero_secreto)\n                escreva(\"\\nVocê precisou de \", tentativas, \" tentativas.\")\n                \n                se (tentativas <= 3) {\n                    escreva(\"\\n⭐ Excelente! Você é um expert!\")\n                } senao se (tentativas <= 5) {\n                    escreva(\"\\n👍 Muito bom! Bom raciocínio!\")\n                } senao {\n                    escreva(\"\\n👌 Conseguiu! Continue praticando!\")\n                }\n            } senao se (palpite < numero_secreto) {\n                escreva(\"\\n📈 O número é MAIOR que \", palpite)\n                min_range = palpite + 1\n            } senao {\n                escreva(\"\\n📉 O número é MENOR que \", palpite)\n                max_range = palpite - 1\n            }\n            \n            se (nao acertou e tentativas < max_tentativas) {\n                inteiro restantes = max_tentativas - tentativas\n                escreva(\"\\nTentativas restantes: \", restantes)\n            }\n        }\n        \n        se (nao acertou) {\n            escreva(\"\\n😞 Que pena! Suas tentativas acabaram.\")\n            escreva(\"\\nO número era \", numero_secreto)\n            escreva(\"\\nTente novamente!\")\n        }\n        \n        escreva(\"\\n\\nObrigado por jogar! 🎮\")\n    }\n}",
