    question: "Sistema de Notas Completo com Estatísticas",
    content: "Sistema completo: cadastrar alunos, notas, calcular médias, aprovações e estatísticas da turma:",
    hint: "Use vetores paralelos para alunos e notas. Implemente funções para cada funcionalidade.",
    answer: "Sistema Acadêmico Completo",
    solution: "programa {\n    cadeia nomes[5]\n    real notas1[5], notas2[5], notas3[5], medias[5]\n    inteiro total_alunos = 0\n    \n    funcao cadastrar_aluno() {\n        se (total_alunos < 5) {\n            escreva(\"\\n=== CADASTRO DE ALUNO ===\\n\")\n            escreva(\"Nome do aluno: \")\n            leia(nomes[total_alunos])\n            \n            escreva(\"Nota 1: \")\n            leia(notas1[total_alunos])\n            escreva(\"Nota 2: \")\n            leia(notas2[total_alunos])\n            escreva(\"Nota 3: \")\n            leia(notas3[total_alunos])\n            \n            medias[total_alunos] = (notas1[total_alunos] + notas2[total_alunos] + notas3[total_alunos]) / 3\n            \n            total_alunos++\n            escreva(\"\\n✅ Aluno cadastrado com sucesso!\")\n        } senao {\n            escreva(\"\\n❌ Limite de alunos atingido (máximo 5)!\")\n        }\n    }\n    \n    funcao exibir_boletim() {\n        se (total_alunos == 0) {\n            escreva(\"\\n❌ Nenhum aluno cadastrado!\")\n            retorne\n        }\n        \n        escreva(\"\\n=== BOLETIM DA TURMA ===\\n\")\n        para (inteiro i = 0; i < total_alunos; i++) {\n            escreva(\"\\nAluno: \", nomes[i], \"\\n\")\n            escreva(\"Nota 1: \", notas1[i], \"\\n\")\n            escreva(\"Nota 2: \", notas2[i], \"\\n\")\n            escreva(\"Nota 3: \", notas3[i], \"\\n\")\n            escreva(\"Média: \", medias[i], \"\\n\")\n            \n            se (medias[i] >= 7.0) {\n                escreva(\"Situação: ✅ APROVADO\\n\")\n            } senao se (medias[i] >= 5.0) {\n                escreva(\"Situação: ⚠️ RECUPERAÇÃO\\n\")\n            } senao {\n                escreva(\"Situação: ❌ REPROVADO\\n\")\n            }\n            escreva(\"------------------------\")\n        }\n    }\n    \n    funcao estatisticas_turma() {\n        se (total_alunos == 0) {\n            escreva(\"\\n❌ Nenhum aluno cadastrado!\")\n            retorne\n        }\n        \n        real soma_medias = 0, maior_media = medias[0], menor_media = medias[0]\n        inteiro aprovados = 0, recuperacao = 0, reprovados = 0\n        cadeia melhor_aluno = nomes[0], pior_aluno = nomes[0]\n        \n        para (inteiro i = 0; i < total_alunos; i++) {\n            soma_medias = soma_medias + medias[i]\n            \n            se (medias[i] > maior_media) {\n                maior_media = medias[i]\n                melhor_aluno = nomes[i]\n            }\n            \n            se (medias[i] < menor_media) {\n                menor_media = medias[i]\n                pior_aluno = nomes[i]\n            }\n            \n            se (medias[i] >= 7.0) {\n                aprovados++\n            } senao se (medias[i] >= 5.0) {\n                recuperacao++\n            } senao {\n                reprovados++\n            }\n        }\n        \n        real media_turma = soma_medias / total_alunos\n        \n        escreva(\"\\n=== ESTATÍSTICAS DA TURMA ===\\n\")\n        escreva(\"Total de alunos: \", total_alunos, \"\\n\")\n        escreva(\"Média da turma: \", media_turma, \"\\n\")\n        escreva(\"\\nSituação dos alunos:\\n\")\n        escreva(\"✅ Aprovados: \", aprovados, \" (\", (aprovados * 100) / total_alunos, \"%)\\n\")\n        escreva(\"⚠️ Recuperação: \", recuperacao, \" (\", (recuperacao * 100) / total_alunos, \"%)\\n\")\n        escreva(\"❌ Reprovados: \", reprovados, \" (\", (reprovados * 100) / total_alunos, \"%)\\n\")\n        escreva(\"\\nDestaques:\\n\")\n        escreva(\"🏆 Melhor aluno: \", melhor_aluno, \" (\", maior_media, \")\\n\")\n        escreva(\"📚 Precisa de ajuda: \", pior_aluno, \" (\", menor_media, \")\\n\")\n    }\n    \n    funcao inicio() {\n        inteiro opcao\n        \n        faca {\n            escreva(\"\\n=== SISTEMA ACADÊMICO ===\\n\")\n            escreva(\"1 - Cadastrar aluno\\n\")\n            escreva(\"2 - Exibir boletim\\n\")\n            escreva(\"3 - Estatísticas da turma\\n\")\n            escreva(\"4 - Buscar aluno\\n\")\n            escreva(\"0 - Sair\\n\")\n            escreva(\"\\nEscolha uma opção: \")\n            leia(opcao)\n            \n            escolha (opcao) {\n                caso 1: cadastrar_aluno() pare\n                caso 2: exibir_boletim() pare\n                caso 3: estatisticas_turma() pare\n                caso 4:\n                    se (total_alunos == 0) {\n                        escreva(\"\\n❌ Nenhum aluno cadastrado!\")\n                    } senao {\n                        cadeia nome_busca\n                        logico encontrado = falso\n                        \n                        escreva(\"\\nDigite o nome do aluno: \")\n                        leia(nome_busca)\n                        \n                        para (inteiro i = 0; i < total_alunos; i++) {\n                            se (nomes[i] == nome_busca) {\n                                escreva(\"\\n=== DADOS DO ALUNO ===\\n\")\n                                escreva(\"Nome: \", nomes[i], \"\\n\")\n                                escreva(\"Notas: \", notas1[i], \" | \", notas2[i], \" | \", notas3[i], \"\\n\")\n                                escreva(\"Média: \", medias[i], \"\\n\")\n                                \n                                se (medias[i] >= 7.0) {\n                                    escreva(\"Situação: ✅ APROVADO\")\n                                } senao se (medias[i] >= 5.0) {\n                                    escreva(\"Situação: ⚠️ RECUPERAÇÃO\")\n                                } senao {\n                                    escreva(\"Situação: ❌ REPROVADO\")\n                                }\n                                encontrado = verdadeiro\n                                pare\n                            }\n                        }\n                        \n                        se (nao encontrado) {\n                            escreva(\"\\n❌ Aluno não encontrado!\")\n                        }\n                    }\n                    pare\n                caso 0: escreva(\"\\n👋 Sistema encerrado!\") pare\n                caso contrario: escreva(\"\\n❌ Opção inválida!\")\n            }\n        } enquanto (opcao != 0)\n    }\n}",
    explanation: "Sistemas completos integram múltiplas funcionalidades. Use funções para organizar o código e facilitar manutenção.",
